import { MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { mix, uv, color } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  const root = new Group();

  // Backdrop with vertical gradient
  const backdropGeom = new PlaneGeometry(7, 5.5);
  const gradientNode = mix(color('#0b0b10'), color('#14141a'), uv.y);
  const backdropMat = new MeshBasicNodeMaterial();
  backdropMat.colorNode = gradientNode;
  const backdrop = new Mesh(backdropGeom, backdropMat);
  backdrop.position.set(0, 0, 0);
  root.add(backdrop);

  // Accent underline rule
  const underlineGeom = new PlaneGeometry(2.2, 0.05);
  const underlineMat = new MeshStandardNodeMaterial();
  underlineMat.colorNode = color('#ff2a38');
  underlineMat.emissiveNode = color('#ff2a38');
  underlineMat.emissiveIntensity = 1.2;
  const underline = new Mesh(underlineGeom, underlineMat);
  underline.position.set(0, -0.15, 0);
  underline.scale.x = 0; // start collapsed
  root.add(underline);

  // Text items
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];

  // Mapping role -> visual parameters
  const roleMap = {
    kicker: { y: 1.7, fontSize: 18, color: '#e8ecf2', letterSpacingPx: 0.12 * 18 },
    hero: { y: null, fontSize: 124, color: '#16161d', letterSpacingPx: -0.015 * 124 },
    body: { y: -0.8, fontSize: 26, color: '#16161d', letterSpacingPx: 0 },
    caption: { y: -1.9, fontSize: 18, color: '#16161d', letterSpacingPx: 0.08 * 18 },
  };

  // Pre‑defined hero line Y positions (two stacked lines)
  const heroLinesY = [0.9, 0.25];

  const textObjects = [];
  let heroIndex = 0;

  for (const item of items) {
    const role = item.role || 'body';
    const spec = roleMap[role] || {};
    const fontSize = spec.fontSize;
    const colorHex = spec.color;
    const letterSpacing = spec.letterSpacingPx ?? 0;
    const align = 'left';
    const x = -3.1;

    // Determine Y position
    let y;
    if (role === 'hero') {
      y = heroLinesY[heroIndex++] ?? 0;
    } else {
      y = spec.y ?? 0;
    }

    // Main text
    const txt = ctx.fontAtlas.createText(item.text, {
      fontSize,
      color: colorHex,
      align,
      letterSpacingPx: letterSpacing,
    });
    txt.position.set(x, y, 0);
    root.add(txt);
    textObjects.push(txt);

    // Hero shadow (letterpress edge)
    if (role === 'hero') {
      const shadow = ctx.fontAtlas.createText(item.text, {
        fontSize,
        color: '#16161d',
        align,
        letterSpacingPx: letterSpacing,
      });
      shadow.position.set(x, y, -0.02);
      root.add(shadow);
      textObjects.push(shadow);
    }
  }

  // Entrance animation (rise‑in with stagger)
  const tl = gsap.timeline({ defaults: { ease: 'power3.out' } });
  textObjects.forEach((obj, i) => {
    // start offset and invisible
    obj.position.y += 0.4;
    obj.traverse((c) => {
      if (c.material) {
        c.material.transparent = true;
        c.material.opacity = 0;
      }
    });
    tl.to(
      obj.position,
      { y: obj.position.y - 0.4, duration: 0.7, ease: 'power3.out' },
      i * 0.08
    );
    tl.to(
      obj,
      { opacity: 1, duration: 0.7, ease: 'power3.out' },
      i * 0.08
    );
  });

  // Underline scale animation after hero lands (after last hero block)
  const heroBlocks = textObjects.filter((o) => o.userData?.role === 'hero' || o.userData?.role === 'heroShadow');
  const heroEndTime = heroBlocks.length * 0.08 + 0.7;
  tl.to(
    underline.scale,
    {
      x: 1,
      duration: 0.5,
      ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
    },
    heroEndTime
  );

  // Cleanup
  root.userData.cleanup = () => {
    // dispose geometries & materials
    backdropGeom.dispose();
    backdropMat.dispose();
    underlineGeom.dispose();
    underlineMat.dispose();
    textObjects.forEach((obj) => {
      obj.traverse((c) => {
        if (c.geometry) c.geometry.dispose();
        if (c.material) c.material.dispose();
      });
    });
    // kill GSAP timelines
    tl.kill();
  };

  // No event handlers required for this node
  root.userData.handlers = {};

  return root;
}
